    @EventHandler( payloadType=CreateDocumentEvent.class )
    public void handle( CreateDocumentEvent event) {
	    LOGGER.info("handling CreateDocumentEvent - " + event );
	    Document entity = new Document();
            entity.setDocumentId( event.getDocumentId() );
            entity.setFileName( event.getFileName() );
            entity.setUploadedDate( event.getUploadedDate() );
            entity.setDocumentType( event.getDocumentType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDocument( entity );
    }

