    @EventHandler( payloadType=UpdateDocumentEvent.class )
    public void handle( UpdateDocumentEvent event) {
    	LOGGER.info("handling UpdateDocumentEvent - " + event );
    	
	    Document entity = new Document();
            entity.setDocumentId( event.getDocumentId() );
            entity.setFileName( event.getFileName() );
            entity.setUploadedDate( event.getUploadedDate() );
            entity.setPolicy( event.getPolicy() );
            entity.setClaim( event.getClaim() );
            entity.setApplication( event.getApplication() );
            entity.setCustomer( event.getCustomer() );
            entity.setDocumentType( event.getDocumentType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindDocument( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDocument( entity );        
    }
    
