    /**
     * Method to retrieve the Document via an DocumentPrimaryKey.
     * @param 	id Long
     * @return 	Document
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Document handle( FindDocumentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getDocumentId() );
    }
    
    /**
     * Method to retrieve a collection of all Documents
     *
     * @param	query	FindAllDocumentQuery 
     * @return 	List<Document> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Document> handle( FindAllDocumentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindDocument,
 * but only if the id matches
 *
 * @param		entity	Document
 */
	protected void emitFindDocument( Document entity ) {
		LOGGER.info("handling emitFindDocument" );
		
	    queryUpdateEmitter.emit(FindDocumentQuery.class,
	                            query -> query.getFilter().getDocumentId().equals(entity.getDocumentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDocument
	 * 
	 * @param		entity	Document
	 */
	protected void emitFindAllDocument( Document entity ) {
		LOGGER.info("handling emitFindAllDocument" );
		
	    queryUpdateEmitter.emit(FindAllDocumentQuery.class,
	                            query -> true,
	                            entity);
	}

